/// <summary>
/// Executes an operation, retrying it a bounded number of times when it throws.
/// </summary>
public class RetryPolicy

/// <summary>
/// Invokes <paramref name="operation"/> and retries it while it throws, up to <paramref name="maxAttempts"/> attempts.
/// </summary>
/// <typeparam name="T">The type of value produced by the operation.</typeparam>
/// <param name="operation">The operation to execute.</param>
/// <param name="maxAttempts">The maximum number of attempts to make.</param>
/// <returns>The value returned by the first successful invocation of <paramref name="operation"/>.</returns>
/// <exception cref="InvalidOperationException">Thrown when the operation fails on every attempt.</exception>
public T Execute<T>(Func<T> operation, int maxAttempts)
